package dev.zomboid.tacz;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.*;import com.cleannrooster.dungeons_iso.mod.Mod;public class BareChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError(n);}public static class Stack {public boolean empty=true;public boolean isEmpty(){return empty;}}public static class Player extends Minecraft.Player {public Stack stack=new Stack();public boolean reachable=true;public Object getMainHandItem(){return stack;}public Vec3 getEyePosition(){return new Vec3(0,1.6,0);}public boolean canInteractWithEntity(Object e,double extra){return reachable;}}public static class Entity {public boolean alive=true;public boolean isAlive(){return alive;}public Vec3 getEyePosition(){return new Vec3(0,1.6,2);}public Entity getBoundingBox(){return this;}public Vec3 getCenter(){return new Vec3(0,.9,2);}}public static class Level {public boolean blocked;public Hit clip(net.minecraft.world.level.ClipContext c){return new Hit(blocked,new Vec3(0,1.6,.2));}}public static class Hit {public boolean blocked;public Vec3 p;public Hit(boolean blocked,Vec3 p){this.blocked=blocked;this.p=p;}public String getType(){return blocked?"BLOCK":"MISS";}public Vec3 getLocation(){return p;}}public static void main(String[] args){Minecraft mc=Minecraft.M;Player p=new Player();Entity zombie=new Entity();Level level=new Level();mc.player=p;mc.level=level;Mod.enabled=true;Mod.crosshairTarget=new EntityHitResult(zombie,zombie.getCenter());Object wrong=new Object();mc.hitResult=wrong;BareHand.prepare();check(mc.crosshairPickEntity==zombie&&mc.hitResult instanceof EntityHitResult);mc.hitResult=wrong;level.blocked=true;BareHand.prepare();check(mc.hitResult==wrong);level.blocked=false;p.reachable=false;BareHand.prepare();check(mc.hitResult==wrong);p.reachable=true;p.stack.empty=false;BareHand.prepare();check(mc.hitResult==wrong);p.stack.empty=true;mc.screen=new Object();BareHand.prepare();check(mc.hitResult==wrong);mc.screen=null;Mod.enabled=false;BareHand.prepare();check(mc.hitResult==wrong);Mod.enabled=true;zombie.alive=false;BareHand.prepare();check(mc.hitResult==wrong);zombie.alive=true;Mod.crosshairTarget=new Hit(false,new Vec3(0,0,2));BareHand.prepare();check(mc.hitResult==wrong);System.out.println("Passed "+n+" bare hand targeting checks (API doubles)");}}
